package cache

import (
	"encoding/json"
	"fmt"
	"hash/crc32"
	"os"
	"path/filepath"
	"reflect"
	"sort"
	"testing"
)

// Opt-in paired codec comparison over the exact summaries generated by the
// expanded-JSONL footprint fixture. The old codec remains test-only.
func TestSummaryMatchedFootprint(t *testing.T) {
	root := os.Getenv("TRUNK_SUMMARY_MATCHED")
	if root == "" {
		t.Skip("opt-in matched fixture")
	}
	totals := map[string]int64{}
	byDay := map[int64]int64{}
	e := filepath.WalkDir(filepath.Join(root, "summaries"), func(path string, d os.DirEntry, e error) error {
		if e != nil {
			return e
		}
		if d.IsDir() {
			return nil
		}
		raw, e := os.ReadFile(path)
		if e != nil {
			return e
		}
		totals["files"]++
		totals["new_file_bytes"] += int64(len(raw))
		totals["old_file_bytes"] += headerSize
		for at := headerSize; at < len(raw); {
			if at+8 > len(raw) {
				return fmt.Errorf("short frame")
			}
			n := int(order.Uint32(raw[at:]))
			crc := order.Uint32(raw[at+4:])
			at += 8
			if n < 8 || at+n > len(raw) {
				return fmt.Errorf("bad frame")
			}
			chunk := raw[at : at+n]
			at += n
			if crc32.Checksum(chunk, checksum) != crc {
				return fmt.Errorf("CRC mismatch")
			}
			switch string(chunk[:8]) {
			case "SUMROLL0":
				totals["calendar_rollup_bytes"] += int64(n + 8)
				totals["calendar_rollup_rows"] += int64((n - 24) / calendarRollupRowSize)
			case "SUMDAY00":
				day, from, to, sums, e := decodeSummaryDay(chunk)
				if e != nil {
					return e
				}
				old, e := baselineSummaryDay(day, from, to, sums, true)
				if e != nil {
					return e
				}
				decoded, e := baselineDecodeDay(old)
				if e != nil {
					return e
				}
				if len(decoded) != len(sums) {
					return fmt.Errorf("baseline hour mismatch")
				}
				for i := range sums {
					sums[i].DurationWidth = 0
					if !reflect.DeepEqual(sums[i], decoded[i]) {
						return fmt.Errorf("baseline semantic mismatch")
					}
				}
				totals["sealed_packets"]++
				totals["new_sealed_bytes"] += int64(n)
				totals["old_sealed_bytes"] += int64(len(old))
				totals["new_decoded_bytes"] += int64(order.Uint32(chunk[16:]))
				totals["old_decoded_bytes"] += int64(order.Uint32(old[16:]))
				totals["old_file_bytes"] += int64(8 + len(old))
				byDay[day] += int64(n)
			case "SUMCOL00":
				var s Summary
				if e = decodeSummary(chunk, &s); e != nil {
					return e
				}
				old, e := baselineEncodeSummary(s)
				if e != nil {
					return e
				}
				totals["open_hours"]++
				totals["new_open_hour_bytes"] += int64(n + 8)
				totals["old_open_hour_bytes"] += int64(len(old) + 8)
				totals["old_file_bytes"] += int64(8 + len(old))
			default:
				return fmt.Errorf("unknown summary record")
			}
		}
		return nil
	})
	if e != nil {
		t.Fatal(e)
	}
	totals["new_without_calendar_rollups"] = totals["new_file_bytes"] - totals["calendar_rollup_bytes"]
	var days []int64
	for _, v := range byDay {
		days = append(days, v)
	}
	sort.Slice(days, func(i, j int) bool { return days[i] < days[j] })
	if len(days) == 0 {
		t.Fatal("no fixture packets")
	}
	totals["whole_day_min_bytes"], totals["whole_day_median_bytes"], totals["whole_day_max_bytes"] = days[0], days[len(days)/2], days[len(days)-1]
	result, e := json.MarshalIndent(totals, "", "  ")
	if e != nil {
		t.Fatal(e)
	}
	if e = os.WriteFile(filepath.Join(root, "summary-comparison.json"), append(result, '\n'), 0644); e != nil {
		t.Fatal(e)
	}
	t.Log(string(result))
}
